#!/usr/bin/env bash
# Compare the server config of two Velociraptor releases, to catch upstream
# config changes (new or removed settings, changed defaults) before an
# upgrade ships:
#   1. New installs: the config each release generates (`config generate`).
#   2. Existing installs: a config generated by the OLD release, as the old
#      and the new release load it (`config show`). The new release must be
#      able to load it at all, and any value it fills in differently shows up.
#
#   scripts/config-drift.sh OLD NEW [REPORT.md]
#
# OLD/NEW: a release version (v0.77.2) or a linux-amd64 asset URL (raw or
# .gz, as recorded in binaries.lock). Runs the binaries, so it needs a
# linux/amd64 host (CI runners), e.g. locally:
#   docker run --rm --platform linux/amd64 -v "$PWD:/r" -w /r ubuntu:26.04 \
#     bash -c 'apt-get update -qq && apt-get install -yqq curl jq >/dev/null && scripts/config-drift.sh v0.77.2 v0.77.3'
# Exit status: 0 = no differences, 1 = differences found, 2 = error
# (including "the new release cannot load the old config").
set -euo pipefail

old_ref="${1:?usage: config-drift.sh OLD NEW [REPORT.md]}"
new_ref="${2:?usage: config-drift.sh OLD NEW [REPORT.md]}"
report="${3:-/dev/stdout}"
work="$(mktemp -d)"
trap 'rm -rf -- "$work"' EXIT

fetch() {
  local ref="$1" out="$2" url
  local base="https://github.com/Velocidex/velociraptor/releases/download"
  local urls=()
  if [[ "$ref" == http* ]]; then
    urls=("$ref")
  else
    local asset="velociraptor-${ref}-linux-amd64"
    urls=("$base/$ref/$asset" "$base/$ref/$asset.gz" "$base/${ref%.*}/$asset")
  fi
  for url in "${urls[@]}"; do
    if curl -fsSL --retry 3 --retry-delay 2 -o "$out.dl" "$url" 2>/dev/null; then
      case "$url" in
        *.gz) gzip -dc "$out.dl" > "$out"; rm -f "$out.dl" ;;
        *) mv "$out.dl" "$out" ;;
      esac
      chmod +x "$out"
      return 0
    fi
  done
  echo "could not download $ref" >&2
  exit 2
}

# Flatten a JSON config (from `config show --json`) to sorted
# "path = value" lines. Key material, nonces and other per-install random
# values are masked, and build stamps dropped, so only structure and
# defaults remain.
flatten() {
  # shellcheck disable=SC2016
  jq -r '
    def mask: if type == "string" and (test("-----BEGIN") or length > 200) then "<redacted>" else . end;
    del(.version, .Client.server_version, .Client.version)
    | walk(if type == "object" then with_entries(
             if (.key | test("(?i)(private_key|certificate|nonce|password|secret|_key$)")) and (.value | type) == "string"
             then .value = "<redacted>" else .value |= mask end)
           else . end)
    | paths(scalars) as $p
    | "\($p | map(tostring) | join(".")) = \(getpath($p) | tojson)"
  ' "$1" | sort
}

# show BINARY CONFIG: the config as that release loads it, as JSON.
show() { "$1" --config "$2" config show --json 2>/dev/null; }

keys_of() { sed 's/ = .*//' "$1" | sort -u; }
value_of() { grep -F -m1 "$1 = " "$2" | sed 's/^[^=]*= //'; }

# diff_flat A B: sets ADDED, REMOVED (as "path = value") and CHANGED
# ("path: old -> new"), one entry per line.
diff_flat() {
  local a="$1" b="$2" key o n
  ADDED="" REMOVED="" CHANGED=""
  while IFS= read -r key; do
    [ -n "$key" ] && ADDED+="$key = $(value_of "$key" "$b")"$'\n'
  done < <(comm -13 <(keys_of "$a") <(keys_of "$b"))
  while IFS= read -r key; do
    [ -n "$key" ] && REMOVED+="$key = $(value_of "$key" "$a")"$'\n'
  done < <(comm -23 <(keys_of "$a") <(keys_of "$b"))
  while IFS= read -r key; do
    [ -n "$key" ] || continue
    o="$(value_of "$key" "$a")"
    n="$(value_of "$key" "$b")"
    [ "$o" = "$n" ] || CHANGED+="$key: $o -> $n"$'\n'
  done < <(comm -12 <(keys_of "$a") <(keys_of "$b"))
}

lines() { printf '%s' "$1" | sed '/^$/d' | wc -l | tr -d ' '; }

section() {
  local title="$1" body="$2"
  [ "$(lines "$body")" -gt 0 ] || return 0
  echo
  echo "<details><summary>${title} ($(lines "$body"))</summary>"
  echo
  echo '```'
  printf '%s\n' "$body" | sed '/^$/d'
  echo '```'
  echo '</details>'
}

fetch "$old_ref" "$work/old"
fetch "$new_ref" "$work/new"
old_version="$("$work/old" version 2>/dev/null | awk '/^version:/ {print $2}' || true)"
new_version="$("$work/new" version 2>/dev/null | awk '/^version:/ {print $2}' || true)"
old_version="${old_version:-$old_ref}"
new_version="${new_version:-$new_ref}"

# 1. New installs
"$work/old" config generate > "$work/old.yaml" 2>/dev/null
"$work/new" config generate > "$work/new.yaml" 2>/dev/null
show "$work/old" "$work/old.yaml" > "$work/gen.old.json"
show "$work/new" "$work/new.yaml" > "$work/gen.new.json"
flatten "$work/gen.old.json" > "$work/gen.old"
flatten "$work/gen.new.json" > "$work/gen.new"
diff_flat "$work/gen.old" "$work/gen.new"
gen_added="$ADDED" gen_removed="$REMOVED" gen_changed="$CHANGED"

# 2. Existing installs keep their old config: the new release must load it.
load_ok=true
load_added="" load_removed="" load_changed=""
if "$work/new" --config "$work/old.yaml" config show --json > "$work/load.new.json" 2> "$work/load.err"; then
  flatten "$work/load.new.json" > "$work/load.new"
  diff_flat "$work/gen.old" "$work/load.new"
  load_added="$ADDED" load_removed="$REMOVED" load_changed="$CHANGED"
else
  load_ok=false
fi

all="$gen_added$gen_removed$gen_changed$load_added$load_removed$load_changed"
{
  echo "### Server config changes: ${old_version} → ${new_version}"
  echo
  if [ "$load_ok" = true ]; then
    echo "- ✅ ${new_version} loads a config generated by ${old_version}."
  else
    echo "- ❌ ${new_version} **cannot load** a config generated by ${old_version}:"
    echo '```'
    head -20 "$work/load.err"
    echo '```'
  fi
  echo "- New installs (\`config generate\`): $(lines "$gen_added") added, $(lines "$gen_removed") removed, $(lines "$gen_changed") changed defaults."
  echo "- Existing configs as the new release loads them: $(lines "$load_added") added, $(lines "$load_removed") removed, $(lines "$load_changed") changed."
  section "New installs: settings added" "$gen_added"
  section "New installs: settings removed" "$gen_removed"
  section "New installs: defaults changed" "$gen_changed"
  section "Existing configs: settings added at load" "$load_added"
  section "Existing configs: settings removed at load" "$load_removed"
  section "Existing configs: values changed at load" "$load_changed"
  echo
  if [ -z "$all" ]; then
    echo "No differences."
  else
    echo "Existing installs keep their persisted \`server.config.yaml\`. Review whether reconcile mode in the entrypoint should apply any of these, and whether the README needs an upgrade note."
  fi
} > "$report"

[ "$load_ok" = true ] || exit 2
[ -z "$all" ] || exit 1
exit 0
